                ConversionSentence(43, "My brother got a scholarship for higher education.", "میرے بھائی کو اعلیٰ تعلیم کے لیے اسکالرشپ مل گئی۔", "Mere bhai ko aala taleem ke liye scholarship mil gayi."),
                ConversionSentence(44, "We shared our childhood bedroom until high school.", "ہم ہائی اسکول تک بچپن کا ایک ہی کمرہ شیئر کرتے تھے۔", "Hum high school tak bachpan ka aik hi kamra share kartay thay."),
                ConversionSentence(45, "A strong family stands united against every challenge.", "ایک مضبوط خاندان ہر مشکل کے خلاف متحد رہتا ہے۔", "Aik mazboot khandan har mushkil ke khilaaf muttahid rehta hai."),
                ConversionSentence(46, "My mother teaches us the value of honesty and hard work.", "میری والدہ ہمیں ایمانداری اور محنت کی اہمیت سکھاتی ہیں۔", "Meri walida humein imandari aur mehnat ki ahmiyat sikhati hain."),
                ConversionSentence(47, "I bought a special birthday gift for my mother.", "میں نے اپنی والدہ کے لیے سالگرہ کا خاص تحفہ خریدا ہے۔", "Mein ne apni walida ke liye saal-girah ka khaas tohfa khareeda hai."),
                ConversionSentence(48, "Relatives visited us from our ancestral village.", "ہمارے آبائی گاؤں سے رشتہ دار ہمارے ہاں تشریف لائے۔", "Hamaray aabayi gao se rishta-daar hamaray haan tashreef laaye."),
