                ConversionSentence(14, "I believe in respectful, open, and objective dialogue.", "میں باہمی احترام، کھلی اور تعمیری گفتگو پر یقین رکھتا ہوں۔", "Mein baahmi ihtiram, khuli aur ta'meeri guftagu par yaqeen rakhta hoon."),
                ConversionSentence(15, "Why did you decide to leave your previous job?", "آپ نے اپنی پچھلی ملازمت چھوڑنے کا فیصلہ کیوں کیا؟", "Aap ne apni pichli mulazmat chhorrnay ka faisla kyun kiya?"),
                ConversionSentence(16, "I am seeking new growth opportunities and broader challenges.", "میں ترقی کے نئے مواقع اور وسیع تر چیلنجز تلاش کر رہا ہوں۔", "Mein taraqi ke naye mawaqe aur wasee-tar challenges talash kar raha hoon."),
                ConversionSentence(17, "What motivates you to deliver your best work?", "آپ کو بہترین کام کرنے کے لیے کیا چیز تحریک دیتی ہے؟", "Aap ko behtareen kaam karne ke liye kya cheez tehreek deti hai?"),
                ConversionSentence(18, "Creating tangible impact and learning continuously drives me.", "مثبت اثر پیدا کرنا اور مسلسل کچھ نیا سیکھنا مجھے تحریک دیتا ہے۔", "Musbat asar paida karna aur musalsal kuch naya seekhna mujhe tehreek deta hai."),
                ConversionSentence(19, "How soon would you be able to join our organization?", "آپ ہماری تنظیم میں کتنی جلدی شامل ہو سکتے ہیں؟", "Aap hamari tanzeem mein kitni jaldi shamil ho saktay hain?"),
                ConversionSentence(20, "I can join immediately after serving my two-week notice.", "میں اپنے دو ہفتے کے نوٹس کے بعد فوراً جوائن کر سکتا ہوں۔", "Mein apne do haftay ke notice ke baad fauran join kar sakta hoon."),
                ConversionSentence(21, "Are you comfortable with working in rotational shifts?", "کیا آپ باری باری شفٹوں میں کام کرنے کے لیے تیار ہیں؟", "Kya aap baari baari shifts mein kaam karne ke liye tayar hain?"),
                ConversionSentence(22, "Yes, I am flexible and adapt easily to shift timings.", "جی ہاں، میں وقت کے معاملے میں لچکدار اور پرسکون ہوں۔", "Jee haan, mein waqt ke maamlay mein lachakdaar aur pursukoon hoon."),
                ConversionSentence(23, "Can you describe a situation where you overcame failure?", "کیا آپ ایسی صورتحال بتا سکتے ہیں جہاں آپ نے ناکامی پر قابو پایا؟", "Kya aap aisi soorathal bata saktay hain jahan aap ne nakami par qaaboo paaya?"),
                ConversionSentence(24, "I analyzed the root cause and implemented preventive safeguards.", "میں نے بنیادی وجہ سمجھی اور مستقبل کے لیے حفاظتی اقدامات کیے۔", "Mein ne bunyadi wajah samjhi aur mustaqbil ke liye hifazati iqdaamaat kiye."),
                ConversionSentence(25, "I hold a Bachelor's degree in Computer Science from NUST.", "میں نے نسٹ سے کمپیوٹر سائنس میں بیچلر کی ڈگری حاصل کی ہے۔", "Mein ne NUST se Computer Science mein Bachelor ki degree hasil ki hai."),
                ConversionSentence(26, "I recently completed an advanced certification in Cloud Computing.", "میں نے حال ہی میں کلاؤڈ کمپیوٹنگ میں ایڈوانسڈ سرٹیفیکیشن مکمل کی۔", "Mein ne haal hi mein Cloud Computing mein advanced certification mukammal ki."),
                ConversionSentence(27, "How do you stay updated with industry trends?", "آپ انڈسٹری کے نئے رجحانات سے کیسے باخبر رہتے ہیں؟", "Aap industry ke naye rujhanaat se kaisay ba-khabar rehtay hain?"),
                ConversionSentence(28, "I regularly read research blogs and attend tech meetups.", "میں باقاعدگی سے بلاگز پڑھتا ہوں اور ٹیکنالوجی کی محافل میں شریک ہوتا ہوں۔", "Mein baqaidgi se blogs parhta hoon aur tech meetups mein shareek hota hoon."),
                ConversionSentence(29, "What is your leadership style when managing juniors?", "جونیئر ساتھیوں کو سنبھالتے وقت آپ کا قیادت کا انداز کیا ہوتا ہے؟", "Junior sathiyon ko sambhaltay waqt aap ka qiyadat ka andaaz kya hota hai?"),
                ConversionSentence(30, "I lead with empathy, mentorship, and clear accountability.", "میں رہنمائی، ہمدردی، اور واضح اہداف کے ساتھ لیڈ کرتا ہوں۔", "Mein rehnumai, hamdardi, aur waazeh ahdaaf ke sath lead karta hoon."),
                ConversionSentence(31, "We were very impressed by your portfolio and GitHub projects.", "ہم آپ کے پورٹ فولیو اور گٹ ہب پروجیکٹس سے بہت متاثر ہوئے۔", "Hum aap ke portfolio aur GitHub projects se bohat mutasir hue."),
                ConversionSentence(32, "Thank you, I put a lot of passion into crafting clean code.", "شکریہ، میں معیاری کوڈ لکھنے میں اپنی پوری لگن لگاتا ہوں۔", "Shukriya, mein meyaari code likhnay mein apni poori lagan lagata hoon."),
                ConversionSentence(33, "What are the key responsibilities for this position?", "اس عہدے کی بنیادی ذمہ داریاں کیا ہیں؟", "Is ohday ki bunyadi zimma-dariyaan kya hain?"),
                ConversionSentence(34, "You will lead product roadmaps and client communications.", "آپ پروڈکٹ کے روڈ میپ اور کلائنٹ رابطوں کی قیادت کریں گے۔", "Aap product ke roadmap aur client rabton ki qiyadat karein gay."),
                ConversionSentence(35, "Does the company support professional development courses?", "کیا کمپنی ملازمین کے پیشہ ورانہ کورسز کی فیس برداشت کرتی ہے؟", "Kya company mulazmeen ke peshawarana courses ki fees bardasht karti hai?"),
                ConversionSentence(36, "Yes, we provide an annual learning stipend to every employee.", "جی ہاں، ہم ہر ملازم کو سالانہ لرننگ الاؤنس فراہم کرتے ہیں۔", "Jee haan, hum har mulazim ko salana learning allowance faraham kartay hain."),
                ConversionSentence(37, "How does your team measure quarterly success?", "آپ کی ٹیم سہ ماہی کامیابی کا تعین کیسے کرتی ہے؟", "Aap ki team seh-maahi kamyabi ka ta'ayyun kaisay karti hai?"),
                ConversionSentence(38, "We use OKRs to track delivery quality and user adoption.", "ہم ڈیلیوری کے معیار اور یوزرز کی تعداد کے ذریعے ناپتے ہیں۔", "Hum delivery ke meyaar aur users ki taadaad ke zariye naaptay hain."),
                ConversionSentence(39, "Our HR team will contact you regarding the final decision.", "ہماری ایچ آر ٹیم حتمی فیصلے سے متعلق آپ سے رابطہ کرے گی۔", "Hamari HR team hatmi faislay se muta'alliq aap se rabta karegi."),
                ConversionSentence(40, "I look forward to hearing from you and contributing to your team.", "مجھے آپ کے مثبت جواب اور ٹیم میں حصہ ڈالنے کا شدت سے انتظار ہے۔", "Mujhe aap ke musbat jawab aur team mein hissa daalnay ka shiddat se intezar hai."),
                ConversionSentence(41, "Could you provide references from your past supervisors?", "کیا آپ اپنے پچھلے سپروائزرز کی معلومات فراہم کر سکتے ہیں؟", "Kya aap apne pichlay supervisors ki ma'loomat faraham kar saktay hain?"),
                ConversionSentence(42, "Certainly, I have attached their letters of recommendation.", "یقیناً، میں نے ان کے سفارشی خطوط ساتھ منسلک کر دیے ہیں۔", "Yaqeenan, mein ne un ke sifarishi khutooth sath munsalik kar diye hain."),
                ConversionSentence(43, "Dress professionally and arrive ten minutes before time.", "شائستہ لباس پہنیں اور وقت سے دس منٹ پہلے پہنچیں۔", "Shaista libas pehnein aur waqt se das minute pehle pohanchein."),
                ConversionSentence(44, "Maintain steady eye contact and confidence while answering.", "جواب دیتے وقت نظریں ملا کر اور پراعتماد انداز میں بات کریں۔", "Jawab detay waqt nazrein mila kar aur pur-aitemaad andaaz mein baat karein."),
                ConversionSentence(45, "Highlight your practical problem-solving skills with examples.", "عملی مثالوں کے ساتھ اپنی مسئلہ حل کرنے کی صلاحیت اجاگر کریں۔", "Amali misalon ke sath apni masla hal karne ki salahiyat ujagar karein."),
                ConversionSentence(46, "Be honest about what you know and eager to learn the rest.", "جو جانتے ہیں اس میں سچے رہیں اور باقی سیکھنے کا جذبہ رکھیں۔", "Jo jaantay hain us mein sachay rahein aur baaqi seekhnay ka jazba rakhein."),
                ConversionSentence(47, "A polite thank-you email after the interview leaves a great impression.", "انٹرویو کے بعد شکریے کی شائستہ ای میل بہت اچھا تاثر چھوڑتی ہے۔", "Interview ke baad shukriye ki shaista email bohat acha ta'assur chhorrti hai."),
                ConversionSentence(48, "We are delighted to extend an official job offer to you.", "ہمیں آپ کو ملازمت کی باضابطہ پیشکش کرتے ہوئے خوشی ہو رہی ہے۔", "Humein aap ko mulazmat ki ba-zabita peshkash kartay hue khushi ho rahi hai."),
                ConversionSentence(49, "I accept the offer with gratitude and enthusiasm.", "میں شکرگزاری اور خوشی کے ساتھ اس پیشکش کو قبول کرتا ہوں۔", "Mein shukr-guzari aur khushi ke sath is peshkash ko qabool karta hoon."),
                ConversionSentence(50, "Welcome aboard to our dynamic and growing organization!", "ہماری متحرک اور تیزی سے ترقی کرتی تنظیم میں خوش آمدید!", "Hamari mutaharrik aur tezi se taraqi karti tanzeem mein khush aamdeed!")
            )),

