                ConversionSentence(2, "May I see your passport and flight ticket, please?", "کیا میں برائے مہربانی آپ کا پاسپورٹ اور ٹکٹ دیکھ سکتا ہوں؟", "Kya mein baraye meharbani aap ka passport aur ticket dekh sakta hoon?"),
                ConversionSentence(3, "How many bags are you checking in today?", "آج آپ کتنے بیگ بک کروا رہے ہیں؟", "Aaj aap kitnay bag book karwa rahay hain?"),
                ConversionSentence(4, "This suitcase exceeds the twenty-kilogram baggage limit.", "یہ سوٹ کیس بیس کلوگرام کے وزن کی حد سے زیادہ ہے۔", "Yeh suitcase bees kilogram ke wazan ki hadd se zyada hai."),
                ConversionSentence(5, "Would you like a window seat or an aisle seat?", "کیا آپ کھڑکی والی نشست پسند کریں گے یا راہداری والی؟", "Kya aap khirrki wali nashist pasand karein gay ya raahdari wali?"),
                ConversionSentence(6, "Here is your boarding pass, your gate number is 14.", "یہ آپ کا بورڈنگ پاس ہے، آپ کا گیٹ نمبر 14 ہے۔", "Yeh aap ka boarding pass hai, aap ka gate number 14 hai."),
                ConversionSentence(7, "Flight boarding will commence forty minutes prior to departure.", "بورڈنگ پرواز کی روانگی سے چالیس منٹ پہلے شروع ہوگی۔", "Boarding parwaz ki rawangi se 40 minute pehle shuru hogi."),
                ConversionSentence(8, "Please empty your pockets and place metal items in the tray.", "براہ کرم جیبیں خالی کریں اور دھاتی اشیاء ٹرے میں رکھیں۔", "Barah-e-karam jaibein khaali karein aur dhaati ashiya tray mein rakhein."),
                ConversionSentence(9, "Do you have any liquids over one hundred milliliters?", "کیا آپ کے پاس سو ملی لیٹر سے زیادہ مقدار کا کوئی مائع ہے؟", "Kya aap ke paas 100 ml se zyada miqdaar ka koi liquid hai?"),
                ConversionSentence(10, "Please fasten your seatbelts during takeoff and landing.", "پرواز بھرتے اور اترتے وقت اپنی سیٹ بیلٹ باندھ کر رکھیں۔", "Parwaz bhartay aur utartay waqt apni seatbelt baandh kar rakhein."),
                ConversionSentence(11, "What is the purpose of your visit to Dubai?", "آپ کے دبئی کے دورے کا بنیادی مقصد کیا ہے؟", "Aap ke Dubai ke doray ka bunyadi maqsad kya hai?"),
                ConversionSentence(12, "I am visiting for tourism and leisure with my family.", "میں اپنے اہل خانہ کے ساتھ سیاحت اور تفریح کے لیے جا رہا ہوں۔", "Mein apne ahl-e-khana ke sath sayahat aur tafreeh ke liye ja raha hoon."),
                ConversionSentence(13, "How long do you intend to stay in the country?", "آپ کا ملک میں کتنے دن قیام کرنے کا ارادہ ہے؟", "Aap ka mulk mein kitnay din qayaam karne ka irada hai?"),
                ConversionSentence(14, "I have a return ticket booked for fourteen days later.", "میری چودہ دن بعد کی واپسی کی کنفرم ٹکٹ موجود ہے۔", "Meri chaudah din baad ki wapsi ki confirm ticket maujood hai."),
                ConversionSentence(15, "Where is the baggage claim conveyor belt for flight PK-701?", "فلائٹ پی کے 701 کے سامان وصولی کی بیلٹ کہاں ہے؟", "Flight PK-701 ke samaan wasooli ki belt kahan hai?"),
                ConversionSentence(16, "My black trolley luggage is missing from the belt.", "میرا کالا ٹرالی بیگ کنویئر بیلٹ پر نہیں مل رہا۔", "Mera kaala trolley bag conveyor belt par nahi mil raha."),
                ConversionSentence(17, "Please visit the lost and found counter with your baggage tag.", "براہ کرم اپنے بیگیج ٹیگ کے ساتھ گمشدہ سامان کے کاؤنٹر جائیں۔", "Barah-e-karam apne baggage tag ke sath lost and found counter jayein."),
                ConversionSentence(18, "Where can I exchange US dollars to local currency?", "میں امریکی ڈالرز مقامی کرنسی میں کہاں تبدیل کروا سکتا ہوں؟", "Mein US Dollars maqami currency mein kahan tabdeel karwa sakta hoon?"),
                ConversionSentence(19, "There is a licensed currency exchange kiosk near exit gate 3.", "گیٹ نمبر 3 کے پاس لائسنس یافتہ منی ایکسچینج موجود ہے۔", "Gate number 3 ke paas licensed money exchange maujood hai."),
                ConversionSentence(20, "Where can I buy a local tourist SIM card with 4G data?", "مجھے 4G انٹرنیٹ والی مقامی سیاحتی سم کہاں سے ملے گی؟", "Mujhe 4G data wali maqami tourist SIM kahan se milay gi?"),
                ConversionSentence(21, "Telecom counters are located right next to the airport exit.", "ٹیلی کام کاؤنٹرز ہوائی اڈے سے نکلتے ہی دائیں جانب ہیں۔", "Telecom counters airport se nikaltay hi daayein jaanib hain."),
                ConversionSentence(22, "Is there an official airport taxi queue outside?", "کیا باہر ہوائی اڈے کی سرکاری ٹیکسی کی قطار موجود ہے؟", "Kya bahir airport ki sarkari taxi ki qataar maujood hai?"),
                ConversionSentence(23, "Please avoid unauthorized cabs and use official counters.", "غیر تصدیق شدہ ٹیکسیوں سے بچیں اور سرکاری کاؤنٹر استعمال کریں۔", "Ghair tasdeeq-shuda taxiyon se bachein aur sarkari counter istemal karein."),
                ConversionSentence(24, "Our flight has been delayed by two hours due to dense fog.", "گہری دھند کے باعث ہماری پرواز میں دو گھنٹے کی تاخیر ہو گئی ہے۔", "Gehri dhund ke ba'is hamari parwaz mein do ghantay ki takheer ho gayi hai."),
                ConversionSentence(25, "Airline staff is distributing complimentary refreshments.", "ایئرلائن کا عملہ انتظار گاہ میں مفت ریفریشمنٹس بانٹ رہا ہے۔", "Airline ka amla intezar-gah mein muft refreshments baant raha hai."),
                ConversionSentence(26, "Can I bring this camera tripod in my cabin handbag?", "کیا میں یہ کیمرہ اسٹینڈ ہاتھ والے بیگ میں لے جا سکتا ہوں؟", "Kya mein yeh camera stand haath walay bag mein le ja sakta hoon?"),
                ConversionSentence(27, "Small tripods are allowed inside cabin hand baggage.", "چھوٹے ٹرائی پوڈز ہینڈ بیگ میں لے جانے کی اجازت ہے۔", "Chhotay tripods hand bag mein le jaanay ki ijazat hai."),
                ConversionSentence(28, "Please put your mobile phones in airplane mode.", "براہ کرم اپنے موبائل فونز فلائٹ موڈ پر لگا لیں۔", "Barah-e-karam apne mobile phones flight mode par laga lein."),
                ConversionSentence(29, "Cabin crew will now serve complimentary meals.", "جہاز کا عملہ اب کھانا پیش کرے گا۔", "Jahaaz ka amla ab khana pesh karega."),
                ConversionSentence(30, "Would you like chicken with rice or vegetarian pasta?", "آپ چکن چاول پسند کریں گے یا سبزی والا پاستا؟", "Aap chicken chawal pasand karein gay ya pasta?"),
                ConversionSentence(31, "The view of mountain clouds from the window is breathtaking.", "کھڑکی سے پہاڑوں کے اوپر بادلوں کا نظارہ انتہائی دلفریب ہے۔", "Khirrki se paharon ke oopar baadlon ka nazara intehai dil-fareb hai."),
                ConversionSentence(32, "We are experiencing slight turbulence, please remain seated.", "تھوڑے جھٹکے محسوس ہو رہے ہیں، براہ کرم بیٹھے رہیں۔", "Thorray jhatkay mehsoos ho rahay hain, barah-e-karam baithay rahein."),
                ConversionSentence(33, "The captain announced that we will land in twenty minutes.", "کپتان نے اعلان کیا ہے کہ ہم بیس منٹ میں لینڈ کریں گے۔", "Captain ne elan kiya hai ke hum 20 minute mein land karein gay."),
                ConversionSentence(34, "Please ensure your seat back is in an upright position.", "براہ کرم یقینی بنائیں کہ آپ کی نشست بالکل سیدھی ہے۔", "Barah-e-karam yaqeeni banayein ke aap ki seat bilkul seedhi hai."),
                ConversionSentence(35, "Welcome to Heathrow International Airport, London.", "ہیتھرو انٹرنیشنل ایئرپورٹ لندن میں خوش آمدید۔", "Heathrow International Airport London mein khush aamdeed."),
                ConversionSentence(36, "Follow the yellow directional signs for passport control.", "پاسپورٹ کنٹرول اور امیگریشن کے لیے پیلے سائن بورڈز دیکھیں۔", "Passport control ke liye peelay signboards dekhein."),
                ConversionSentence(37, "Have your arrival immigration landing card ready.", "اپنا امیگریشن ارائیول کارڈ ہاتھ میں تیار رکھیں۔", "Apna immigration arrival card haath mein tayar rakhein."),
                ConversionSentence(38, "Place your right thumb on the biometric scanner.", "بائیو میٹرک اسکینر پر اپنے دائیں ہاتھ کا انگوٹھا رکھیں۔", "Biometric scanner par apne daayein haath ka angootha rakhein."),
                ConversionSentence(39, "Your visa stamp is valid for thirty days from today.", "آپ کے ویزے کی مہر آج سے تیس دن کے لیے کارآمد ہے۔", "Aap ke visa ki mohar aaj se tees din ke liye kaar-aamad hai."),
                ConversionSentence(40, "Enjoy your memorable holiday and stay in our country.", "ہمارے ملک میں اپنی یادگار چھٹیوں کا لطف اٹھائیں۔", "Hamaray mulk mein apni yaadgar chhuttiyon ka lutf uthayein."),
                ConversionSentence(41, "Do you have anything to declare to customs officers?", "کیا کسٹمز والوں کو دکھانے کے لیے آپ کے پاس کوئی چیز ہے؟", "Kya customs walon ko dikhanay ke liye aap ke paas koi cheez hai?"),
                ConversionSentence(42, "I have only personal clothing, books, and electronics.", "میرے پاس صرف ذاتی کپڑے، کتابیں اور الیکٹرانکس ہیں۔", "Mere paas sirf zaati kapray, kitabein aur electronics hain."),
                ConversionSentence(43, "You can proceed through the green duty-free channel.", "آپ گرین ڈیوٹی فری چینل سے باہر جا سکتے ہیں۔", "Aap green channel se bahir ja saktay hain."),
                ConversionSentence(44, "Where is the subway metro station connected to the airport?", "ہوائی اڈے سے جڑا میٹرو ٹرین اسٹیشن کہاں ہے؟", "Airport se jurra metro train station kahan hai?"),
                ConversionSentence(45, "Take the escalator down to basement level 1 for trains.", "ٹرینوں کے لیے ایسکلیٹر سے بیسمنٹ لیول 1 پر تشریف لے جائیں۔", "Trainon ke liye escalator se basement level 1 par jayein."),
                ConversionSentence(46, "How much is a single express ticket to downtown?", "شہر کے مرکز تک ایک ایکسپریس ٹکٹ کی کیا قیمت ہے؟", "Shehar ke markaz tak aik express ticket ki kya qeemat hai?"),
                ConversionSentence(47, "Traveling by express train takes only twenty-five minutes.", "ایکسپریس ٹرین سے سفر میں صرف پچیس منٹ لگتے ہیں۔", "Express train se safar mein sirf 25 minute lagtay hain."),
                ConversionSentence(48, "Keep your boarding pass safe for claiming airline miles.", "ایئرلائن میلز پوائنٹس کلیم کرنے کے لیے بورڈنگ پاس سنبھال کر رکھیں۔", "Airline miles points claim karne ke liye boarding pass sambhal kar rakhein."),
                ConversionSentence(49, "Traveling expands your worldview and creates lifelong memories.", "سفر انسان کے ذہن کو کشادہ اور یادوں کو لازوال بناتا ہے۔", "Safar insaan ke zehan ko kushada aur yaadon ko la-zawal banata hai."),
                ConversionSentence(50, "Safe travels and may every journey be blessed and enjoyable!", "آپ کا ہر سفر خیر و عافیت اور خوشیوں سے بھرپور رہے!", "Aap ka har safar khair-o-aafiyat aur khushiyon se bharpoor rahay!")
            )),

            // 8. Hotel & Accommodation (50 Sentences)
            ConversionTopic(8, "Hotel & Accommodation", "ہوٹل اور قیام", "home", "Booking rooms, room service, and check-out.", listOf(
                ConversionSentence(1, "I have a room reservation under the name Muhammad Ali.", "محمد علی کے نام سے میری کمرے کی بکنگ موجود ہے۔", "Muhammad Ali ke naam se meri kamray ki booking maujood hai."),
                ConversionSentence(2, "What time is the standard check-in and check-out?", "ہوٹل میں آمد اور روانگی کا مقررہ وقت کیا ہے؟", "Hotel mein aamad aur rawangi ka muqarrara waqt kya hai?"),
                ConversionSentence(3, "Is complimentary breakfast included with this deluxe room?", "کیا اس ڈیلکس کمرے کے ساتھ ناشتہ مفت شامل ہے؟", "Kya is deluxe kamray ke sath nashta muft shamil hai?"),
                ConversionSentence(4, "Breakfast is served daily from 7:00 AM to 10:30 AM.", "ناشتہ روزانہ صبح 7 سے ساڑھے 10 بجے تک پیش کیا جاتا ہے۔", "Nashta rozana subah 7 se 10:30 bajay tak pesh kiya jata hai."),
                ConversionSentence(5, "Here is your electronic room keycard for room 405.", "یہ کمرہ نمبر 405 کے لیے آپ کا الیکٹرانک چابی کارڈ ہے۔", "Yeh kamra number 405 ke liye aap ka electronic keycard hai."),
                ConversionSentence(6, "Could you please send an extra set of clean towels?", "کیا آپ مزید دو صاف تولیے بھجوا سکتے ہیں؟", "Kya aap mazeed do saaf toliye bhijwa saktay hain?"),
                ConversionSentence(7, "The air conditioner in my room isn't cooling properly.", "میرے کمرے کا اے سی صحیح ٹھنڈک نہیں کر رہا ہے۔", "Mere kamray ka AC sahi thandak nahi kar raha hai."),
                ConversionSentence(8, "We will send an engineer immediately to fix it.", "ہم اسے ٹھیک کرنے کے لیے فوری طور پر انجینئر بھیجتے ہیں۔", "Hum isay theek karne ke liye fauri engineer bhejtay hain."),
                ConversionSentence(9, "What is the Wi-Fi password for guests in the room?", "کمرے میں مہمانوں کے لیے وائی فائی کا پاس ورڈ کیا ہے؟", "Kamray mein mehmanon ke liye Wi-Fi ka password kya hai?"),
                ConversionSentence(10, "Could we request a late check-out at 2:00 PM tomorrow?", "کیا ہمیں کل دوپہر 2 بجے تک دیر سے روانگی کی اجازت مل سکتی ہے؟", "Kya humein kal dopahar 2 bajay tak late check-out ki ijazat mil sakti hai?"),
                ConversionSentence(11, "Is there a swimming pool and fitness gym on the premises?", "کیا ہوٹل میں سوئمنگ پول اور جم کی سہولت موجود ہے؟", "Kya hotel mein swimming pool aur gym ki sahulat maujood hai?"),
                ConversionSentence(12, "The rooftop pool is open until 10 PM every night.", "چھت پر پول ہر رات دس بجے تک کھلا رہتا ہے۔", "Chhat par pool har raat 10 bajay tak khula rehta hai."),
                ConversionSentence(13, "Can I order room service for dinner right now?", "کیا میں ابھی کمرے میں رات کے کھانے کا آرڈر دے سکتا ہوں؟", "Kya mein abhi kamray mein raat ke khanay ka order de sakta hoon?"),
                ConversionSentence(14, "Please bring a club sandwich and fresh lemonade to room 405.", "کمرہ 405 میں ایک کلب سینڈوچ اور تازہ لیمونیڈ لا دیں۔", "Kamra 405 mein aik club sandwich aur taaza lemonade laa dein."),
                ConversionSentence(15, "Please do not disturb, I need to rest quietly.", "براہ کرم ڈسٹرب نہ کریں، مجھے آرام کی ضرورت ہے۔", "Barah-e-karam disturb na karein, mujhe aaram ki zaroorat hai."),
                ConversionSentence(16, "Please clean my room while I am out exploring the city.", "جب میں باہر سیر کروں تو میرے کمرے کی صفائی کر دیں۔", "Jab mein bahir sair karoon to mere kamray ki safai kar dein."),
                ConversionSentence(17, "Where can I find an iron and ironing board?", "مجھے استری اور استری بورڈ کہاں سے مل سکتا ہے؟", "Mujhe istari aur ironing board kahan se mil sakta hai?"),
                ConversionSentence(18, "Housekeeping will deliver an iron to your room shortly.", "ہاؤس کیپنگ کا عملہ جلد آپ کے کمرے میں استری پہنچا دے گا۔", "Housekeeping ka amla jald aap ke kamray mein istari pohancha dega."),
                ConversionSentence(19, "Does the hotel provide laundry and dry cleaning services?", "کیا ہوٹل کپڑے دھلائی اور ڈرائی کلیننگ کی سروس دیتا ہے؟", "Kya hotel kapray dhulayee aur dry cleaning ki service deta hai?"),
                ConversionSentence(20, "Yes, same-day express laundry is available upon request.", "جی ہاں، ایک ہی دن میں کپڑے تیار کرنے کی سہولت دستیاب ہے۔", "Jee haan, express laundry ki sahulat dastyab hai."),
                ConversionSentence(21, "Is there a safety digital locker inside the wardrobe?", "کیا الماری کے اندر ڈیجیٹل سیف لاکر موجود ہے؟", "Kya almaari ke andar digital safe locker maujood hai?"),
                ConversionSentence(22, "Yes, you can set your own 4-digit security code.", "جی ہاں، آپ اپنا چار ہندسوں کا خفیہ کوڈ سیٹ کر سکتے ہیں۔", "Jee haan, aap apna 4-digit code set kar saktay hain."),
                ConversionSentence(23, "Could you arrange a wake-up call for 6:00 AM tomorrow?", "کیا آپ کل صبح 6 بجے کی ویک اپ کال کا انتظام کر سکتے ہیں؟", "Kya aap kal subah 6 bajay ki wake-up call ka intezam kar saktay hain?"),
                ConversionSentence(24, "Certainly, our front desk will call your room telephone.", "یقیناً، ہمارا ریسپشن عملہ آپ کے کمرے میں کال کرے گا۔", "Yaqeenan, hamara reception amla aap ke phone par call karega."),
                ConversionSentence(25, "Can the concierge arrange a city sightseeing tour for us?", "کیا ہوٹل ہمارے لیے شہر کی سیر کا ٹور بک کر سکتا ہے؟", "Kya hotel hamaray liye shehar ki sair ka tour book kar sakta hai?"),
                ConversionSentence(26, "We offer guided day trips to all famous historical landmarks.", "ہم تمام مشہور تاریخی مقامات کے معلوماتی ٹورز کرواتے ہیں۔", "Hum tamam mashhoor tareekhi muqamaat ke tours karwatay hain."),
                ConversionSentence(27, "Is tap water safe to drink or should we use bottled water?", "کیا نلکے کا پانی پینے کے قابل ہے یا منرل واٹر پئیں؟", "Kya nalkay ka paani peenay ke qabil hai ya mineral water piyein?"),
                ConversionSentence(28, "We provide two complimentary bottles of drinking water daily.", "ہم روزانہ پینے کے پانی کی دو بوتلیں مفت فراہم کرتے ہیں۔", "Hum rozana peenay ke paani ki 2 botlein muft faraham kartay hain."),
                ConversionSentence(29, "Could you provide an extra blanket for the bed?", "کیا آپ بستر کے لیے ایک اضافی کمبل فراہم کر سکتے ہیں؟", "Kya aap bistar ke liye aik izaafi kambal faraham kar saktay hain?"),
                ConversionSentence(30, "The shower water temperature is easy to adjust.", "شاور کے پانی کا درجہ حرارت آسانی سے کنٹرول ہو جاتا ہے۔", "Shower ke paani ka darja-e-hararat aasaani se control ho jata hai."),
                ConversionSentence(31, "Can we leave our luggage at the reception after check-out?", "کیا چیک آؤٹ کے بعد ہم اپنا سامان ریسپشن پر رکھوا سکتے ہیں؟", "Kya check-out ke baad hum apna samaan reception par rakhwa saktay hain?"),
                ConversionSentence(32, "Yes, free luggage storage is provided for all departing guests.", "جی ہاں، تمام مہمانوں کے لیے سامان کی مفت حفاظت کا انتظام ہے۔", "Jee haan, tamam mehmanon ke liye samaan ki muft hifazat ka intezam hai."),
                ConversionSentence(33, "Is there an airport shuttle service available early morning?", "کیا صبح سویرے ایئرپورٹ کے لیے شٹل گاڑی دستیاب ہے؟", "Kya subah sawayray airport ke liye shuttle gari dastyab hai?"),
                ConversionSentence(34, "Yes, airport shuttles leave every hour on the hour.", "جی ہاں، ہر گھنٹے بعد ایئرپورٹ کے لیے گاڑی روانہ ہوتی ہے۔", "Jee haan, har ghantay baad airport ke liye gari rawana hoti hai."),
                ConversionSentence(35, "We would like to upgrade our room to a sea-facing suite.", "ہم اپنا کمرہ سمندر کے رخ والے سویٹ میں اپگریڈ کرنا چاہتے ہیں۔", "Hum apna kamra samandar ke rukh walay suite mein upgrade karna chahtay hain."),
                ConversionSentence(36, "Let me check available suite occupancy for tonight.", "مجھے آج رات کے لیے دستیاب سویٹ چیک کرنے دیں۔", "Mujhe aaj raat ke liye dastyab suite check karne dein."),
                ConversionSentence(37, "Can you call a metered taxi to the hotel entrance?", "کیا آپ ہوٹل کے گیٹ پر میٹر والی ٹیکسی منگوا سکتے ہیں؟", "Kya aap hotel ke gate par metered taxi mangwa saktay hain?"),
                ConversionSentence(38, "Your taxi has arrived and is waiting at the main porch.", "آپ کی ٹیکسی آ گئی ہے اور پورچ میں انتظار کر رہی ہے۔", "Aap ki taxi aa gayi hai aur porch mein intezar kar rahi hai."),
                ConversionSentence(39, "The room view overlooking the city skyline is gorgeous.", "کمرے کی کھڑکی سے شہر کا نظارہ انتہائی شاندار ہے۔", "Kamray ki khirrki se shehar ka nazara intehai shandar hai."),
                ConversionSentence(40, "Are pets allowed inside this hotel property?", "کیا اس ہوٹل میں پالتو جانور ساتھ لانے کی اجازت ہے؟", "Kya is hotel mein paaltu janwar sath laanay ki ijazat hai?"),
                ConversionSentence(41, "This hotel follows a strict no-smoking policy in all rooms.", "اس ہوٹل کے تمام کمروں میں سگریٹ نوشی سختی سے منع ہے۔", "Is hotel ke tamam kamron mein cigarette noshi sakhti se mana hai."),
                ConversionSentence(42, "Can I get an invoice printed in my company's official name?", "کیا بل میری کمپنی کے سرکاری نام سے پرنٹ ہو سکتا ہے؟", "Kya bill meri company ke sarkari naam se print ho sakta hai?"),
                ConversionSentence(43, "Please provide your company tax registration number.", "براہ کرم اپنی کمپنی کا ٹیکس رجسٹریشن نمبر فراہم کریں۔", "Barah-e-karam apni company ka tax number faraham karein."),
                ConversionSentence(44, "The mattress and pillows are exceptionally comfortable.", "گدا اور تکیے غیر معمولی حد تک آرام دہ ہیں۔", "Gadda aur takiye ghair mamooli hadd tak aaram deh hain."),
                ConversionSentence(45, "Could you show me how to operate the digital room thermostat?", "کیا آپ مجھے کمرے کا ڈیجیٹل تھرموسٹیٹ چلانا سکھا سکتے ہیں؟", "Kya aap mujhe thermostat chalana sikha saktay hain?"),
                ConversionSentence(46, "Press the blue arrow to lower temperature and red to increase.", "درجہ حرارت کم کرنے کے لیے نیلا اور بڑھانے کے لیے سرخ بٹن دبائیں۔", "Darja-e-hararat kam karne ke liye neela aur barhanay ke liye surkh button dabayein."),
                ConversionSentence(47, "We really enjoyed our three-night stay at your hotel.", "ہمیں آپ کے ہوٹل میں تین راتوں کا قیام بہت پسند آیا۔", "Humein aap ke hotel mein 3 raaton ka qayaam bohat pasand aaya."),
                ConversionSentence(48, "Your hospitality and attentive staff made our trip wonderful.", "آپ کے عملے کے حسنِ اخلاق اور مہمان نوازی نے سفر یادگار بنایا۔", "Aap ke amlay ke husn-e-akhlaaq ne safar yaadgar banaya."),
                ConversionSentence(49, "Here is your signed check-out folio and payment receipt.", "یہ آپ کی چیک آؤٹ دستاویز اور حتمی ادائیگی کی رسید ہے۔", "Yeh aap ki check-out dastaweez aur adaigi ki raseed hai."),
                ConversionSentence(50, "Thank you for choosing us, we hope to welcome you again!", "ہمارا انتخاب کرنے کا شکریہ، دوبارہ تشریف آوری کا انتظار رہے گا!", "Hamara intikhab karne ka shukriya, dobara khush aamdeed kahein gay!")
            )),

            // 9. Directions & City Navigation (50 Sentences)
            ConversionTopic(9, "Directions & City Navigation", "راستہ اور شہر کی رہنمائی", "explore", "Asking for directions, landmarks, and finding locations.", listOf(
                ConversionSentence(1, "Excuse me, how do I get to the central train station?", "معاف کیجیے گا، میں مرکزی ریلوے اسٹیشن کیسے پہنچوں؟", "Maaf kijiye ga, mein markazi railway station kaisay pohanchon?"),
                ConversionSentence(2, "Go straight for two blocks and then turn left.", "دو چوک تک سیدھے جائیں اور پھر بائیں مڑ جائیں۔", "Do chowk tak seedhay jayein aur phir baayein murr jayein."),
                ConversionSentence(3, "Is the grand national mosque within walking distance?", "کیا قومی جامع مسجد پیدل فاصلے پر ہے؟", "Kya qaumi jamia masjid paidal faslay par hai?"),
                ConversionSentence(4, "Yes, it takes only five to seven minutes on foot.", "جی ہاں، پیدل صرف پانچ سے سات منٹ لگتے ہیں۔", "Jee haan, paidal sirf 5 se 7 minute lagtay hain."),
                ConversionSentence(5, "Take the second right turn after the traffic signal.", "ٹریفک سگنل کے بعد دوسرا دایاں موڑ مڑیں۔", "Traffic signal ke baad dosra daayaan morr murein."),
                ConversionSentence(6, "Where is the nearest automated teller machine (ATM)?", "قریب ترین اے ٹی ایم مشین کہاں ہے؟", "Qareeb tareen ATM machine kahan hai?"),
                ConversionSentence(7, "You can find an ATM inside the petrol station across the street.", "سڑک کے اس پار پیٹرول پمپ کے اندر اے ٹی ایم موجود ہے۔", "Sadak ke us paar petrol pump ke andar ATM maujood hai."),
                ConversionSentence(8, "I seem to be completely lost, can you help me find this address?", "شاید میں راستہ بھول گیا ہوں، کیا آپ یہ پتہ ڈھونڈنے میں مدد کر سکتے ہیں؟", "Shayad mein rasta bhool gaya hoon, kya aap yeh pata dhoondnay mein madad kar saktay hain?"),
                ConversionSentence(9, "Look for the large clock tower, the library is right behind it.", "بڑے کلاک ٹاور کو دیکھیں، لائبریری بالکل اس کے پیچھے ہے۔", "Baray clock tower ko dekhein, library bilkul us ke peechay hai."),
                ConversionSentence(10, "Thank you so much for your kind guidance and help.", "آپ کی رہنمائی اور مدد کا بے حد شکریہ۔", "Aap ki rehnumai aur madad ka be-hadd shukriya."),
                ConversionSentence(11, "Which bus goes directly to the university campus?", "کون سی بس براہ راست یونیورسٹی کیمپس جاتی ہے؟", "Kaun si bus barah-e-raast university campus jaati hai?"),
                ConversionSentence(12, "Bus number 24 stops directly outside the main university gate.", "بس نمبر 24 یونیورسٹی کے مین گیٹ کے باہر رکتی ہے۔", "Bus number 24 university ke main gate ke bahir rukti hai."),
                ConversionSentence(13, "Is this the correct way towards the public general hospital?", "کیا یہ راستہ سرکاری جنرل ہسپتال کی طرف جاتا ہے؟", "Kya yeh rasta sarkari general hospital ki taraf jata hai?"),
                ConversionSentence(14, "You are heading in the opposite direction, turn around.", "آپ الٹی سمت جا رہے ہیں، گاڑی پیچھے موڑ لیں۔", "Aap ulti simt ja rahay hain, gari peechay morr lein."),
                ConversionSentence(15, "Cross the pedestrian bridge to reach the other side safely.", "دوسری طرف باحفاظت جانے کے لیے پیدل پل کا استعمال کریں۔", "Dosri taraf ba-hifazat jaanay ke liye paidal pull istemal karein."),
                ConversionSentence(16, "How far is the international airport from here?", "یہاں سے انٹرنیشنل ایئرپورٹ کتنا دور ہے؟", "Yahan se international airport kitna door hai?"),
                ConversionSentence(17, "It is about fifteen kilometers, roughly twenty minutes by highway.", "تقریباً پندرہ کلومیٹر، ہائی وے سے بیس منٹ کا فاصلہ ہے۔", "Taqreeban 15 km, highway se 20 minute ka fasla hai."),
                ConversionSentence(18, "Can I park my vehicle along this roadside curb?", "کیا میں سڑک کے کنارے گاڑی پارک کر سکتا ہوں؟", "Kya mein sadak ke kinaray gari park kar sakta hoon?"),
                ConversionSentence(19, "No parking is allowed here, your car might get towed away.", "یہاں پارکنگ ممنوع ہے، گاڑی لفٹر اٹھا کر لے جا سکتا ہے۔", "Yahan parking mamnoo hai, car tow ho sakti hai."),
                ConversionSentence(20, "There is a secure underground paid parking plaza nearby.", "قریب ہی زیر زمین محفوظ پیڈ پارکنگ پلازہ موجود ہے۔", "Qareeb hi underground paid parking plaza maujood hai."),
                ConversionSentence(21, "Where can I find an authentic traditional food street?", "خالص روایتی کھانوں کی فوڈ اسٹریٹ کہاں واقع ہے؟", "Khalis riwayati khanon ki food street kahan waqay hai?"),
                ConversionSentence(22, "Anarkali and Fort Road food streets are world famous.", "انارکلی اور فورٹ روڈ فوڈ اسٹریٹس دنیا بھر میں مشہور ہیں۔", "Anarkali aur Fort Road food streets mashhoor hain."),
                ConversionSentence(23, "Keep driving until you see a large overhead flyover bridge.", "ڈرائیو کرتے رہیں جب تک آپ کو بڑا فلائی اوور پل نظر نہ آ جائے۔", "Drive kartay rahein jab tak flyover bridge nazar na aa jaye."),
                ConversionSentence(24, "Take the exit ramp towards Mall Road.", "مال روڈ کی طرف اترنے والے راستے کا انتخاب کریں۔", "Mall Road ki taraf utarnay walay rastay ka intikhab karein."),
                ConversionSentence(25, "Is there any landmark I should look out for?", "کیا کوئی ایسی نشانی ہے جس سے مجھے پہچان ہو سکے؟", "Kya koi aisi nishani hai jis se mujhe pehchan ho sakay?"),
