                ConversionSentence(29, "Which subway metro line goes towards the financial district?", "کون سی میٹرو لائن کاروباری اور مالیاتی مرکز کی طرف جاتی ہے؟", "Kaun si metro line business district ki taraf jaati hai?"),
                ConversionSentence(30, "Board the Orange Metro Line heading northbound.", "شمال کی طرف جانے والی اورنج میٹرو لائن پر سوار ہوں۔", "Shumaal ki taraf jaanay wali Orange Metro Line par sawar hoon."),
                ConversionSentence(31, "How many stops until we arrive at Liberty Market?", "لبرٹی مارکیٹ آنے میں کتنے اسٹاپس باقی ہیں؟", "Liberty Market aanay mein kitnay stops baaqi hain?"),
                ConversionSentence(32, "Get off at the fourth stop right after Gaddafi Stadium.", "قذافی اسٹیڈیم کے فوراً بعد چوتھے اسٹاپ پر اتر جائیں۔", "Qaddafi Stadium ke fauran baad chauthay stop par utar jayein."),
                ConversionSentence(33, "Is this highway toll road or a free public avenue?", "کیا یہ ٹول پلازہ والی ہائی وے ہے یا مفت سڑک؟", "Kya yeh toll plaza wali highway hai ya muft sadak?"),
                ConversionSentence(34, "Keep your electronic toll card ready for automated scanning.", "خودکار اسکیننگ کے لیے اپنا ایم ٹیگ کارڈ تیار رکھیں۔", "Automated scanning ke liye apna M-Tag card tayar rakhein."),
                ConversionSentence(35, "Can you pinpoint our current location on Google Maps?", "کیا آپ گوگل میپس پر ہمارا موجودہ مقام دکھا سکتے ہیں؟", "Kya aap Google Maps par hamara maujooda muqaam dikha saktay hain?"),
                ConversionSentence(36, "Turn on device GPS location for turn-by-turn navigation.", "قدم بہ قدم رہنمائی کے لیے موبائل کا جی پی ایس آن کریں۔", "Qadam ba qadam rehnumai ke liye mobile ka GPS on karein."),
                ConversionSentence(37, "Watch out for speed bumps in residential school zones.", "اسکولوں اور رہائشی علاقوں میں اسپیڈ بریکرز کا خیال رکھیں۔", "School zones mein speed breakers ka khayal rakhein."),
                ConversionSentence(38, "The historic city fort is illuminated beautifully at night.", "رات کے وقت تاریخی قلعہ روشنیوں میں بہت خوبصورت لگتا ہے۔", "Raat ke waqt tareekhi qila roshniyon mein bohat khubsurat lagta hai."),
                ConversionSentence(39, "Where is the main entrance gate for ticket holders?", "ٹکٹ رکھنے والوں کے لیے مرکزی داخلے کا دروازہ کہاں ہے؟", "Ticket rakhnay walon ke liye main entrance gate kahan hai?"),
                ConversionSentence(40, "Entrance for tourists is through the eastern gate.", "سیاحوں کے داخلے کا راستہ مشرقی دروازے سے ہے۔", "Sayahon ke dakhilay ka rasta mashriqi darwazay se hai."),
                ConversionSentence(41, "Can I rent a self-drive car or bicycle in this area?", "کیا اس علاقے میں خود چلانے کے لیے گاڑی یا سائیکل کرائے پر مل سکتی ہے؟", "Kya is ilaqay mein self-drive car ya cycle kiraye par mil sakti hai?"),
                ConversionSentence(42, "Bike-sharing rental docking stations are located all around the park.", "پارک کے ارد گرد سائیکل کرائے کے اسٹیشن موجود ہیں۔", "Park ke gird cycle rental docking stations maujood hain."),
                ConversionSentence(43, "Is this neighborhood safe for solo walking late at night?", "کیا یہ محلہ رات دیر گئے اکیلے پیدل چلنے کے لیے محفوظ ہے؟", "Kya yeh mohalla raat ko akele paidal chalnay ke liye mehfooz hai?"),
                ConversionSentence(44, "Yes, this area is well-lit and patrolled by security police.", "جی ہاں، یہاں اچھی روشنی ہے اور پولیس گشت کرتی ہے۔", "Jee haan, yahan achi roshni hai aur police gasht karti hai."),
                ConversionSentence(45, "Follow the river embankment road for a scenic drive.", "خوبصورت نظارے کے لیے دریا کے کنارے والی سڑک پر چلیں۔", "Khubsurat nazare ke liye darya ke kinaray wali sadak par chalein."),
                ConversionSentence(46, "Where can I hail a yellow auto rickshaw or ride-hailing cab?", "مجھے رکشہ یا آن لائن کیب کہاں سے مل سکتی ہے؟", "Mujhe rickshaw ya online cab kahan se mil sakti hai?"),
                ConversionSentence(47, "You can book an Uber or Bykea directly on your phone.", "آپ اپنے فون سے براہ راست اوبر یا بائیکیا بک کر سکتے ہیں۔", "Aap apne phone se Uber ya Bykea book kar saktay hain."),
                ConversionSentence(48, "Excuse me, which lane should I stay in to go downtown?", "معاف کیجیے گا، شہر جانے کے لیے مجھے کس لین میں رہنا چاہیے؟", "Maaf kijiye ga, shehar jaanay ke liye mujhe kis lane mein rehna chahiye?"),
                ConversionSentence(49, "Stay in the middle lane to avoid the highway exit traffic.", "ہائی وے کے رش سے بچنے کے لیے درمیان والی لین میں رہیں۔", "Highway ke rush se bachnay ke liye darmiyan wali lane mein rahein."),
                ConversionSentence(50, "Wishing you a smooth, safe, and pleasant trip across the city!", "آپ کا پورے شہر کا سفر پرامن، محفوظ اور خوشگوار رہے!", "Aap ka pooray shehar ka safar pursukoon aur mehfooz rahay!")
            )),

