            ConversionTopic(10, "Health & Doctor Clinic", "صحت اور ڈاکٹر کا کلینک", "healing", "Explaining symptoms, booking doctor visits, and checkups.", listOf(
                ConversionSentence(1, "I would like to schedule an appointment with Dr. Farooq.", "میں ڈاکٹر فاروق سے معائنے کا وقت لینا چاہتا ہوں۔", "Mein Dr. Farooq se mu'ainay ka waqt lena chahta hoon."),
                ConversionSentence(2, "What symptoms have you been experiencing lately?", "آپ کو حال ہی میں کیا علامات محسوس ہو رہی ہیں؟", "Aap ko haal hi mein kya alamaat mehsoos ho rahi hain?"),
                ConversionSentence(3, "I have had a severe throbbing headache and fever for two days.", "مجھے دو دن سے شدید سر درد اور تیز بخار ہے۔", "Mujhe do din se shadeed sar dard aur taiz bukhar hai."),
