                ConversionSentence(8, "I am prescribing an antibiotic and pain relief tablets.", "میں اینٹی بائیوٹک اور درد دور کرنے والی گولیاں لکھ رہا ہوں۔", "Mein antibiotic aur dard ki goliyan likh raha hoon."),
                ConversionSentence(9, "Take this medicine twice a day after having meals.", "یہ دوائی دن میں دو مرتبہ کھانا کھانے کے بعد لیں۔", "Yeh dawai din mein do martaba khana khanay ke baad lein."),
                ConversionSentence(10, "Get plenty of bed rest and drink warm water.", "مکمل آرام کریں اور گرم پانی کا کثرت سے استعمال کریں۔", "Mukammal aaram karein aur garam paani ka kasrat se istemal karein."),
                ConversionSentence(11, "Do you have any known allergies to penicillin or sulfur?", "کیا آپ کو پینسلین یا کسی خاص دوا سے الرجی ہے؟", "Kya aap ko penicillin ya kisi dawa se allergy hai?"),
                ConversionSentence(12, "No, doctor, I do not have any known drug allergies.", "نہیں ڈاکٹر صاحب، مجھے کسی دوا سے الرجی نہیں ہے۔", "Nahi doctor sahab, mujhe kisi dawa se allergy nahi hai."),
                ConversionSentence(13, "I have been feeling dizzy whenever I stand up quickly.", "جب میں اچانک کھڑا ہوتا ہوں تو مجھے چکر آتے ہیں۔", "Jab mein achanak kharra hota hoon to mujhe chakkar aatay hain."),
                ConversionSentence(14, "We should run a complete blood count test (CBC) for anemia.", "ہمیں خون کی کمی جانچنے کے لیے سی بی سی ٹیسٹ کروانا چاہیے۔", "Humein khoon ki kami janchnay ke liye CBC test karwana chahiye."),
                ConversionSentence(15, "Please visit the diagnostic laboratory on the ground floor.", "براہ کرم گراؤنڈ فلور پر تشخیصی لیبارٹری تشریف لے جائیں۔", "Barah-e-karam ground floor par diagnostic laboratory jayein."),
                ConversionSentence(16, "How long have you been suffering from this chest congestion?", "آپ کو سینے کی یہ جکڑن کتنے دنوں سے ہے؟", "Aap ko seenay ki yeh jakrran kitnay dinon se hai?"),
                ConversionSentence(17, "It started four days ago with a dry, irritating cough.", "یہ چار دن پہلے خشک کھانسی اور گلے کی خراش سے شروع ہوئی۔", "Yeh 4 din pehle khushk khansi aur kharash se shuru hui."),
                ConversionSentence(18, "I will use the stethoscope to listen to your lungs.", "میں اسٹیتھوسکوپ کے ذریعے آپ کے پھیپھڑوں کی آواز سنوں گا۔", "Mein stethoscope ke zariye aap ke phephton ki aawaz sununga."),
                ConversionSentence(19, "There is mild inflammation in your throat and vocal cords.", "آپ کے گلے اور آواز کی نالیوں میں ہلکی سوزش ہے۔", "Aap ke galay aur aawaz ki naliyon mein halki sozish hai."),
                ConversionSentence(20, "Gargle with lukewarm salt water three times a day.", "نیم گرم نمک والے پانی سے دن میں تین بار غرارے کریں۔", "Neem garam namak walay paani se din mein 3 baar ghararay karein."),
                ConversionSentence(21, "Avoid cold beverages, ice cream, and oily fried foods.", "ٹھنڈے مشروبات، آئس کریم اور تلی ہوئی چیزوں سے پرہیز کریں۔", "Thanday mashroobaat, ice cream aur tali hui cheezon se parhez karein."),
                ConversionSentence(22, "My child is experiencing severe stomach ache and nausea.", "میرے بچے کے پیٹ میں شدید درد اور متلی ہو رہی ہے۔", "Mere bachay ke pait mein shadeed dard aur matli ho rahi hai."),
                ConversionSentence(23, "Let me gently palpate the abdomen to check for tenderness.", "مجھے پیٹ دبا کر چیک کرنے دیں کہ کہیں سوجن تو نہیں ہے۔", "Mujhe pait daba kar check karne dein ke sozish to nahi hai."),
                ConversionSentence(24, "Make sure to give oral rehydration solution (ORS) frequently.", "بچے کو او آر ایس کا محلول وقفے وقفے سے ضرور پلاتے رہیں۔", "Bachay ko ORS ka mehlool waqfay waqfay se zaroor pilatay rahein."),
                ConversionSentence(25, "I twisted my ankle while playing football yesterday.", "کل فٹ بال کھیلتے ہوئے میرے ٹخنے میں موچ آ گئی تھی۔", "Kal football khailtay hue mere takhnay mein moch aa gayi thi."),
                ConversionSentence(26, "We will take an X-ray to rule out any hairline bone fracture.", "ہم ایکس رے کریں گے تاکہ ہڈی کے فریکچر کی تسلی ہو سکے۔", "Hum X-ray karein gay taakay haddi ke fracture ki tasalli ho sakay."),
                ConversionSentence(27, "Apply an ice pack for fifteen minutes to reduce swelling.", "سوجن کم کرنے کے لیے پندرہ منٹ تک برف کی ٹکور کریں۔", "Sozish kam karne ke liye 15 minute barf ki takor karein."),
                ConversionSentence(28, "Keep the injured leg elevated on a soft pillow while resting.", "آرام کرتے وقت زخمی پاؤں نرم تکیے پر اونچا رکھیں۔", "Aaram kartay waqt zakhmi paon takiye par ooncha rakhein."),
                ConversionSentence(29, "Do I need to come back for a follow-up review?", "کیا مجھے دوبارہ معائنے کے لیے آنا پڑے گا؟", "Kya mujhe dobara mu'ainay ke liye aana paray ga?"),
                ConversionSentence(30, "Yes, please come back on Monday with your lab test results.", "جی ہاں، پیر کے روز اپنے ٹیسٹ کی رپورٹ کے ساتھ تشریف لائیں۔", "Jee haan, peer ke roz test report ke sath tashreef laayein."),
                ConversionSentence(31, "Is fasting required before taking this fasting blood glucose test?", "کیا شوگر ٹیسٹ سے پہلے خالی پیٹ رہنا ضروری ہے؟", "Kya sugar test se pehle khaali pait rehna zaroori hai?"),
                ConversionSentence(32, "Do not eat or drink anything except plain water for 8 hours.", "آٹھ گھنٹے تک سادہ پانی کے علاوہ کچھ نہ کھائیں پئیں۔", "8 ghantay tak saada paani ke ilawa kuch na khayein piyein."),
                ConversionSentence(33, "My vision becomes blurry when reading small print on screens.", "اسکرین پر باریک تحریر پڑھتے وقت میری نظر دھندلا جاتی ہے۔", "Screen par bareek tehreer parhtay waqt nazar dhundla jaati hai."),
                ConversionSentence(34, "I recommend consulting an optometrist for an eye exam.", "میں آنکھوں کے معائنے کے لیے ماہرِ امراض چشم کا مشورہ دیتا ہوں۔", "Mein aankhon ke mu'ainay ke liye eye specialist ka mashwara deta hoon."),
                ConversionSentence(35, "Regular physical exercise improves cardiovascular health.", "باقاعدہ ورزش دل اور شریانوں کی صحت کو بہتر بناتی ہے۔", "Baqaida warzish dil aur shariyanon ki sehat ko behtar banati hai."),
                ConversionSentence(36, "A balanced diet rich in vegetables prevents many illnesses.", "سبزیوں سے بھرپور متوازن غذا بیماریوں سے بچاتی ہے۔", "Sabziyon se bharpoor mutawazin ghiza beemariyon se bachati hai."),
