                ConversionSentence(38, "Limit screen time and avoid caffeinated tea before bed.", "سونے سے پہلے موبائل کا استعمال اور چائے کافی پینا بند کریں۔", "Sonay se pehle mobile ka istemal aur chai band karein."),
                ConversionSentence(39, "Drink at least eight glasses of clean water every day.", "روزانہ کم از کم آٹھ گلاس صاف پانی ضرور پئیں۔", "Rozana kam az kam 8 glass saaf paani zaroor piyein."),
                ConversionSentence(40, "My tooth is throbbing with unbearable sharp pain.", "میرے دانت میں ناقابلِ برداشت تیز درد ہو رہا ہے۔", "Mere daant mein na-qabil-e-bardasht taiz dard ho raha hai."),
                ConversionSentence(41, "You need to see a dentist for cavity cleaning and filling.", "آپ کو دانت کی صفائی اور فلنگ کے لیے ڈینٹسٹ کے پاس جانا ہوگا۔", "Aap ko filling ke liye dentist ke paas jaana hoga."),
                ConversionSentence(42, "Vaccination protects children against dangerous diseases.", "حفاظتی ٹیکے بچوں کو خطرناک بیماریوں سے محفوظ رکھتے ہیں۔", "Hifazati teekay bachon ko khatarnaak beemariyon se mehfooz rakhtay hain."),
                ConversionSentence(43, "Always check the expiry date on medicine packaging.", "دواؤں کے پیکٹ پر ایکسپائری کی تاریخ ہمیشہ چیک کریں۔", "Dawaon ke packet par expiry date hamesha check karein."),
                ConversionSentence(44, "Do not stop taking antibiotics midway through the course.", "اینٹی بائیوٹک کا کورس کبھی درمیان میں مت چھوڑیں۔", "Antibiotic ka course kabhi darmiyan mein mat chhorrein."),
                ConversionSentence(45, "Mental health is just as vital as physical well-being.", "ذہنی سکون اور صحت جسمانی تندرستی جتنی ہی اہم ہے۔", "Zehni sukoon aur sehat jismani tandrusti jitni hi ahem hai."),
                ConversionSentence(46, "Practicing deep breathing reduces anxiety and daily tension.", "گہرے سانس لینے کی مشق بے چینی اور دباؤ کو دور کرتی ہے۔", "Gehray saans lene ki mashq be-chaini ko door karti hai."),
                ConversionSentence(47, "Wash your hands thoroughly with soap before handling food.", "کھانا ہاتھ لگانے سے پہلے صابن سے اچھی طرح ہاتھ دھوئیں۔", "Khana haath laganay se pehle saabun se haath dhoein."),
                ConversionSentence(48, "The nurse will apply a sterile bandage over the cut.", "نرس زخم پر جراثیم کش دوا اور پٹی باندھے گی۔", "Nurse zakham par jaraseem-kush dawa aur patti baandhay gi."),
                ConversionSentence(49, "Early detection and checkups make treatment much easier.", "وقت پر معائنہ اور بیماری کی تشخیص علاج کو آسان بناتی ہے۔", "Waqt par mu'aina aur tashkhees ilaaj ko aasan banati hai."),
                ConversionSentence(50, "Wishing you a speedy recovery, good health, and long life!", "اللہ تعالیٰ آپ کو جلد شفائے کاملہ اور لمبی صحت مند زندگی عطا فرمائے!", "Allah Ta'ala aap ko jald shifa-e-kamila aur sehat ata farmaye!")
            ))
        )
    }
}
